sql.where:
family_id = #{familyId}
AND status = 1
AND date >= #{start}
AND date <= #{end}
AND openid = #{openid}

mapper.select:
SELECT category_name AS name, COALESCE(SUM(amount), 0) AS amount
FROM transaction
WHERE family_id = #{familyId}
AND status = 1
AND date >= #{start}
AND date <= #{end}
AND type = 'expense'
GROUP BY category_name
ORDER BY amount DESC

mapper.update:
UPDATE `transaction` t
SET t.status = 0,
    t.voided_at = #{now},
    t.void_reason = #{reason},
    t.voided_by = #{operator}
WHERE t.family_id = #{familyId}
  AND t.openid = #{openid}
  AND t.status = 1
  AND NOT EXISTS (
      SELECT 1 FROM saving_record s WHERE s.linked_transaction_id = t.id
  )
